import bs4
import requests
import re
import json
def task_func(url: str, output_path: str) -> list:
    try:
        if url.startswith("http"):
            response = requests.get(url, verify=False)
            response.raise_for_status()
            content = response.text
        else:
            with open(url, 'r') as file:
                content = file.read()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Could not connect to URL: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"HTTP error occurred: {e}")
    except IOError as e:
        raise IOError(f"Error reading file: {e}")

    try:
        soup = bs4.BeautifulSoup(content, 'html.parser')
        text = soup.get_text()
        phone_numbers = re.findall(r'\b(?:\+?1\s?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}\b', text)
    except Exception as e:
        raise ValueError(f"Error parsing text: {e}")

    try:
        with open(output_path, 'w') as f:
            json.dump(phone_numbers, f)
    except IOError as e:
        raise IOError(f"Error writing to file: {e}")

    return phone_numbers

